nodes.command:
node -e "
const description = '${inputs.description}';
const assetTypes = ${JSON.stringify(inputs.asset_types || [])};

// 关键词到资源类型的映射
const keywordMap = {
  '背景': 'background', '场景': 'background', '地图': 'background',
  '角色': 'character', '立绘': 'character', '表情': 'character', 'NPC': 'character',
  '动画': 'animation', '序列帧': 'animation', '过场': 'animation',
  '特效': 'vfx', '粒子': 'vfx', '转场': 'vfx',
  '瓦片': 'tileset', 'tile': 'tileset'
};

// 分析描述中的资源需求
const detectedTypes = new Set(assetTypes);
Object.entries(keywordMap).forEach(([keyword, type]) => {
  if (description.includes(keyword)) detectedTypes.add(type);
});

// 角色到资源的映射
const roleMap = {
  'background': 'L3_environment_artist',
  'character': 'L3_character_artist',
  'animation': 'L3_animator',
  'vfx': 'L3_vfx_artist',
  'tileset': 'L3_environment_artist'
};

// 生成任务列表
const tasks = [];
[...detectedTypes].forEach((type, idx) => {
  tasks.push({
    type: type,
    role: roleMap[type] || 'L3_environment_artist',
    title: '制作 ' + type + ' 资源',
    priority: type === 'background' ? 1 : (type === 'character' ? 2 : 3),
    output_format: 'PNG'
  });
});

const result = {
  detected_types: [...detectedTypes],
  tasks: tasks,
  total_tasks: tasks.length,
  execution_runtime: 'windows',
  requires_mcp: true
};

console.log(JSON.stringify(result, null, 2));
"

node -e "
const fs = require('fs');
const path = require('path');

const analysis = JSON.parse('${nodes.analyze_scope.output.stdout}');
const taskId = '${inputs.task_id}';
const parentTitle = '${inputs.title}';
const projectRoot = '${inputs.project_root}';

const taskpackDir = path.join(projectRoot, 'design/ai-native/03_taskpacks/generated');
if (!fs.existsSync(taskpackDir)) fs.mkdirSync(taskpackDir, { recursive: true });

const generatedPacks = [];

analysis.tasks.forEach((task, idx) => {
  const subTaskId = taskId + '-art-' + (idx + 1).toString().padStart(2, '0');
  const packPath = path.join(taskpackDir, subTaskId + '.md');

  const content = '# TaskPack: ' + subTaskId + '\n\n' +
    '## 基本信息\n' +
    '- **父任务**: ' + taskId + '\n' +
    '- **标题**: ' + task.title + '\n' +
    '- **角色**: ' + task.role + '\n' +
    '- **类型**: ' + task.type + '\n' +
    '- **优先级**: P' + task.priority + '\n' +
    '- **输出格式**: ' + task.output_format + '\n\n' +
    '## 执行环境\n' +
    '- **运行时**: Windows (MCP Runner)\n' +
    '- **需要 MCP**: 是（智绘 AI 生图）\n\n' +
    '## 输入\n' +
    '- 父任务描述: ' + parentTitle + '\n' +
    '- Art Bible: design/ai-native/01_bibles/art_bible.md\n' +
    '- AI 生图指南: .cursor/rules/06-ai-art-generation.mdc\n\n' +
    '## 交付物\n' +
    '- PNG 资源文件\n' +
    '- 资源配置更新\n' +
    '\n## 验收标准\n' +
    '- [ ] PNG 格式正确\n' +
    '- [ ] 尺寸符合规范\n' +
    '- [ ] 风格与 Art Bible 一致\n' +
    '- [ ] 已更新资源注册表\n';

  fs.writeFileSync(packPath, content);
  generatedPacks.push({ id: subTaskId, path: packPath, role: task.role, type: task.type });
});

console.log(JSON.stringify({ generated: generatedPacks, count: generatedPacks.length }));
"
